package com.bank.firstunique;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.logging.Logger;

// Finds the first one-off transaction code for National Bank of India.
public class FirstUniqueFinder {
    private static final Logger log = Logger.getLogger(FirstUniqueFinder.class.getName());

    // First non-repeating character via LinkedHashMap. O(n), O(distinct).
    public Optional<Character> firstUnique(String codes) {
        if (codes == null) {
            throw new IllegalArgumentException("codes must not be null");
        }
        // LinkedHashMap preserves first-seen order of keys.
        Map<Character, Integer> freq = new LinkedHashMap<>();
        for (char c : codes.toCharArray()) {
            freq.merge(c, 1, Integer::sum);        // count each code
        }
        for (Map.Entry<Character, Integer> e : freq.entrySet()) {
            if (e.getValue() == 1) {               // first with count exactly 1
                final char found = e.getKey();
                log.info(() -> "First unique code = '" + found + "'");
                return Optional.of(e.getKey());
            }
        }
        log.warning(() -> "No unique code found");
        return Optional.empty();                   // every code repeats
    }
}
