package com.bank.firstunique;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: first one-off transaction code.
public class FirstUniqueDemo {
    private static final Logger log = Logger.getLogger(FirstUniqueDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        FirstUniqueFinder finder = new FirstUniqueFinder();

        // Codes: D=debit, C=credit, T=transfer. "DDCTC" → first unique is 'T'.
        log.info(() -> "Result = " + finder.firstUnique("DDCTC"));

        // Every code repeats.
        log.info(() -> "Result = " + finder.firstUnique("DDCC"));
    }
}
